53: // ── Cost governance ───────────────────────────────────────────────────────────
54: 
55: /** The model's own cap on the answer. The worst case is that it uses all of it. */
56: const MAX_OUTPUT_TOKENS = 1400;
57: 
58: /**
59:  * What the model costs, in cents per million tokens.
60:  *
61:  * `AI_INPUT_CENTS_PER_MILLION` and `AI_OUTPUT_CENTS_PER_MILLION` are the
62:  * documented names. Both default to 0, which means "this model costs us
63:  * nothing": a free call spends nothing, so the envelope never binds and the
64:  * office is never blocked by a budget nobody set. Set them, and the ceiling
65:  * binds exactly as it is written — the capsule, the fire, the day and the
66:  * month, narrowest first.
67:  */
68: export type ModelRate = { input: number; output: number };
69: 
70: export function modelRate(env: Record<string, string | undefined> = process.env): ModelRate {
71:   return {
72:     input: centsPerMillion(env.AI_INPUT_CENTS_PER_MILLION),
73:     output: centsPerMillion(env.AI_OUTPUT_CENTS_PER_MILLION),
74:   };
75: }
76: 
77: function centsPerMillion(raw: string | undefined): number {
78:   const value = Number(raw?.trim() ?? "");
79:   if (!Number.isFinite(value) || value <= 0) return 0;
80:   return Math.floor(value);
81: }
82: 
83: /**
84:  * A token is about four characters of English text.
85:  *
86:  * The estimate counts the WHOLE request — the constitution and the office
87:  * state travel with every call — and it is deliberately generous. The gate
88:  * must never under-charge a call, because a cent that is quietly not counted is
89:  * a cent the office will spend a hundred times over.
90:  */
91: function estimateInputTokens(payload: string): number {
92:   return Math.ceil(payload.length / 4);
93: }
94: 
95: /**
96:  * The office's own tables for the model budget and the model spend.
97:  *
98:  * WHY THEY LIVE HERE AND NOT IN A MIGRATION: the schema is applied from
99:  * `migrations/*.sql`, but this module may ship before the migration that
100:  * carries these two tables does, and a model call must never fail because a
101:  * table is missing. So the module that first needs them creates them, once,
102:  * idempotently, and every statement is safe to re-run. When a migration that
103:  * carries the same tables lands, it changes nothing: they are already there.
104:  */
105: let budgetTablesReady: Promise<void> | null = null;
106: 
107: async function ensureBudgetTables(sql: Sql): Promise<void> {
108:   budgetTablesReady ??= (async () => {
109:     await sql`
110:       create table if not exists ai_budget (
111:         id text primary key,
112:         usage_day text not null,
113:         usage_month text not null,
114:         scope text not null,
115:         spent_cents integer not null default 0,
116:         calls integer not null default 0,
117:         updated_at timestamptz not null default now()
118:       )
119:     `;
120:     await sql`create index if not exists ai_budget_scope_idx on ai_budget (scope, usage_day)`;
121:     await sql`create index if not exists ai_budget_month_idx on ai_budget (scope, usage_month)`;
122: 
123:     await sql`
124:       create table if not exists ai_spans (
125:         id text primary key,
126:         trace_id text not null,
127:         span_id text not null,
128:         parent_span_id text,
129:         name text not null,
130:         operation_name text not null,
131:         provider_name text not null,
132:         request_model text not null,
133:         response_model text,
134:         input_tokens integer not null default 0,
135:         output_tokens integer not null default 0,
136:         cost_cents integer not null default 0,
137:         task_id text,
138:         agent_id text,
139:         status text not null default 'ok',
140:         attributes jsonb not null default '{}'::jsonb,
141:         events jsonb not null default '[]'::jsonb,
142:         started_at timestamptz not null,
143:         finished_at timestamptz not null,
144:         created_at timestamptz not null default now()
145:       )
146:     `;
147:     await sql`create index if not exists ai_spans_created_idx on ai_spans (created_at desc)`;
148:     await sql`create index if not exists ai_spans_agent_idx on ai_spans (agent_id, created_at desc)`;
149:   })().catch((error) => {
150:     budgetTablesReady = null; // let the next call retry
151:     throw error;
152:   });
153:   return budgetTablesReady;
154: }
