156: /**
157:  * The three counters the office keeps: this agent's fire, today, and this
158:  * month.
159:  *
160:  * A "fire" is one run of one agent. A capsule call has no memory of when the
161:  * last fire ended, so the durable proxy for "this fire" is what this agent has
162:  * spent today — the same window the delegation's daily cap is counted over.
163:  */
164: function budgetKeys(agentId: string, now: Date): { day: string; month: string; fire: string } {
165:   const day = now.toISOString().slice(0, 10);
166:   const month = now.toISOString().slice(0, 7);
167:   return {
168:     day: `day:${day}`,
169:     month: `month:${month}`,
170:     fire: `fire:${agentId}:${day}`,
171:   };
172: }
173: 
174: type BudgetRow = { id: string; scope: string; spent_cents: number; calls: number };
175: 
176: async function readBudgetState(sql: Sql, agentId: string, now: Date): Promise<BudgetState> {
177:   const keys = budgetKeys(agentId, now);
178:   const rows = await sql<BudgetRow>`
179:     select id, scope, spent_cents, calls from ai_budget
180:     where id = ${keys.day} or id = ${keys.month} or id = ${keys.fire}
181:   `;
182:   const byId = new Map(rows.map((row) => [String(row.id), row]));
183:   const spent = (id: string): number => Number(byId.get(id)?.spent_cents ?? 0);
184:   const calls = (id: string): number => Number(byId.get(id)?.calls ?? 0);
185:   return {
186:     spentTodayCents: spent(keys.day),
187:     spentThisMonthCents: spent(keys.month),
188:     spentThisFireCents: spent(keys.fire),
189:     callsThisFire: calls(keys.fire),
190:     callsToday: calls(keys.day),
191:     callsThisMonth: calls(keys.month),
192:   };
193: }
194: 
195: /**
196:  * Add what a call cost to the counters.
197:  *
198:  * One statement, so the three counters can never disagree, and the increment
199:  * is an arithmetic expression rather than a read-modify-write: two serverless
200:  * instances calling the model at the same time both add their own cost and
201:  * neither loses the other's.
202:  */
203: async function recordSpend(sql: Sql, agentId: string, now: Date, cents: number): Promise<void> {
204:   const keys = budgetKeys(agentId, now);
205:   const day = now.toISOString().slice(0, 10);
206:   const month = now.toISOString().slice(0, 7);
207:   const amount = Math.max(0, Math.round(cents));
208:   await sql`
209:     insert into ai_budget (id, usage_day, usage_month, scope, spent_cents, calls, updated_at)
210:     values (${keys.fire}, ${day}, ${month}, 'fire', ${amount}, 1, now()),
211:            (${keys.day}, ${day}, ${month}, 'day', ${amount}, 1, now()),
212:            (${keys.month}, ${day}, ${month}, 'month', ${amount}, 1, now())
213:     on conflict (id) do update set
214:       spent_cents = ai_budget.spent_cents + excluded.spent_cents,
215:       calls = ai_budget.calls + excluded.calls,
216:       updated_at = now()
217:   `;
218: }
